(() => {
  const title='阿發｜班機延誤申請與諮詢';
  function status(){return `<div class="wf-status" aria-hidden="true"><div class="wf-time">9:41</div><div class="wf-island"></div><div class="wf-signal"><i></i><i></i><i></i><i></i></div><div class="wf-wifi"><span class="wf-wifi-dot"></span></div><div class="wf-battery"></div></div>`;}
  function safari(){return `<div class="wf-safari-address" aria-hidden="true"><div class="wf-address-pill"><div class="wf-site-settings"></div><div class="wf-domain">alpha.com</div><div class="wf-reload"></div></div></div><div class="wf-safari-toolbar" aria-hidden="true"><span class="wf-toolbar-item wf-chevron"></span><span class="wf-toolbar-item wf-chevron forward"></span><span class="wf-toolbar-item wf-share"></span><span class="wf-toolbar-item wf-book"></span><span class="wf-toolbar-item wf-tabs"></span></div><div class="wf-home" aria-hidden="true"></div>`;}
  function header(){return `<div class="s3-header"><button class="s3-back" type="button" data-s6b-action="back" aria-label="返回"><img src="./assets/ic-arrow-black-left-s.svg" alt=""></button><div class="s3-title-group"><div class="s3-title">${title}</div><div class="s3-beta">Beta</div></div></div>`;}
  function bar(){return `<div class="s3-message-bar"><div class="s3-message-row"><div class="s3-message-input">告訴我你想做什麼</div><div class="s3-send"></div></div><p class="s3-message-note">當您傳送訊息，即表示同意「AI告知聲明」。本服務由AI提供，<br>內容僅供參考，實際資訊仍以國泰產險官網公告為準。</p></div>`;}
  function time(){return `<div class="s3-time">10:07 PM 送出</div>`;}
  function view(){return `<div class="s6-device">${status()}${header()}<div class="s6-reminder-thread"><div class="s6-reminder-card-peek" aria-hidden="true"></div><div class="s6-reminder-user"><div class="s3-bubble s3-user-bubble">確認申請</div>${time()}</div><div class="s6-reminder-alpha"><div class="s3-avatar" aria-hidden="true"></div><div class="s3-alpha-body"><div class="s3-bubble-wrap"><div class="s3-bubble s3-alpha-bubble">沒有選擇保單的話，不能申請班機延誤理賠喔。<button class="s6-reminder-link" type="button" data-s6b-action="return-policy">返回繼續選擇保單</button></div>${time()}</div></div></div></div>${bar()}${safari()}</div>`;}
  function legacy(screen,selector){const target=Array.from(screen.querySelectorAll(selector)).find(el=>!el.closest('.htmlized-screen')); if(target) target.click();}
  function apply(){const screen=document.getElementById('policy-reminder-screen'); if(!screen) return; let layer=screen.querySelector(':scope > .htmlized-screen'); if(!layer){layer=document.createElement('div');layer.className='htmlized-screen';screen.appendChild(layer);} layer.innerHTML=view(); layer.querySelectorAll('[data-s6b-action]').forEach(btn=>btn.addEventListener('click',()=>{const action=btn.dataset.s6bAction;if(action==='return-policy') legacy(screen,'#policy-reminder-return'); else if(action==='back') history.back();}));}
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>requestAnimationFrame(apply),{once:true}); else requestAnimationFrame(apply);
})();
